using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Rentals.Domain.Leasing;
using Rentals.Domain.Properties;

namespace Rentals.Infrastructure.Persistence.Configurations;

internal sealed class PropertyConfiguration : IEntityTypeConfiguration<Property>
{
    public void Configure(EntityTypeBuilder<Property> builder)
    {
        // Ids are generated by the client so creates can be replayed idempotently.
        builder.Property(p => p.Id).ValueGeneratedNever();
        builder.Property(p => p.Name).HasMaxLength(120);
        builder.Property(p => p.Address).HasMaxLength(200);
        builder.Property(p => p.City).HasMaxLength(100);
        builder.Property(p => p.RowVersion).IsRowVersion();

        builder.HasMany(p => p.Units)
            .WithOne(u => u.Property)
            .HasForeignKey(u => u.PropertyId)
            .OnDelete(DeleteBehavior.Restrict);
        builder.Navigation(p => p.Units).UsePropertyAccessMode(PropertyAccessMode.Field);

        builder.HasIndex(p => p.Name);
    }
}

internal sealed class UnitConfiguration : IEntityTypeConfiguration<Unit>
{
    public void Configure(EntityTypeBuilder<Unit> builder)
    {
        builder.Property(u => u.Id).ValueGeneratedNever();
        builder.Property(u => u.UnitNumber).HasMaxLength(20);
        builder.Property(u => u.MonthlyRent).HasPrecision(10, 2);
        builder.Property(u => u.RowVersion).IsRowVersion();

        builder.HasOne(u => u.UnitType)
            .WithMany()
            .HasForeignKey(u => u.UnitTypeId)
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasMany(u => u.Leases)
            .WithOne()
            .HasForeignKey(l => l.UnitId)
            .OnDelete(DeleteBehavior.Restrict);
        builder.Navigation(u => u.Leases).UsePropertyAccessMode(PropertyAccessMode.Field);

        // Unit numbers are unique within a property, ignoring removed units.
        builder.HasIndex(u => new { u.PropertyId, u.UnitNumber })
            .IsUnique()
            .HasFilter("[DeletedAt] IS NULL");
    }
}

internal sealed class UnitTypeConfiguration : IEntityTypeConfiguration<UnitType>
{
    public void Configure(EntityTypeBuilder<UnitType> builder)
    {
        builder.Property(t => t.Id).ValueGeneratedNever();
        builder.Property(t => t.Name).HasMaxLength(60);
        builder.HasIndex(t => t.Name).IsUnique();
    }
}

internal sealed class LeaseConfiguration : IEntityTypeConfiguration<Lease>
{
    public void Configure(EntityTypeBuilder<Lease> builder)
    {
        builder.Property(l => l.Id).ValueGeneratedNever();
        builder.HasIndex(l => new { l.UnitId, l.StartDate, l.EndDate });
        builder.HasIndex(l => l.ApplicationId).IsUnique();
    }
}
